
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_absp1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_absp1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.319026066445823e+01, -1.173485969754558e+01, -9.750158959845326e+00, -7.105967697201526e+00, -3.698866471680055e+00, 4.856746656797087e-01, 5.279911363594986e+00, 1.022374500621341e+01, 1.442448873807342e+01, 1.597369012636315e+01, 9.882973019173072e+00, 9.086362632952671e-02, -4.621752996613223e-01, 9.674662883584187e-02, 5.120830913002699e-01, 6.791723614901364e-01, 6.913759684334814e-01, 6.465363751414372e-01, 6.034182953231157e-01, 5.743481847691260e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


